/**
 * DEM (demographic) data model, driven by the NEMSIS 3.5.1 XSDs.
 *
 * The section/group/field specs and every NEMSIS Defined List are generated by
 * scripts/nemsis/gen-dem-schema.py into dem-schema.generated.ts. Agency data is
 * stored as a tree of `DemNode` rows (table public.nemsis_dem_nodes): one root
 * node per section (dAgency, dContact, …) and one child node per group instance
 * (ContactInfoGroup, PersonnelGroup, LicensureGroup, …). Each node keeps the
 * values of its own leaf elements. dem-tree.ts renders the tree to DEMDataSet XML
 * in XSD order.
 */
import { DEM_DEFINED_LISTS, DEM_SECTION_SPECS } from "./dem-schema.generated";

export interface DemAttrSpec { name: string; list: string | null; required: boolean }

export interface DemFieldSpec {
  kind: "field";
  tag: string;
  label: string;
  repeat: boolean;
  min: number;
  nillable?: boolean;
  /** NEMSIS Defined List key (DEM_DEFINED_LISTS) for the value itself. */
  list?: string;
  /** Allowed Not Values, [code, label]. */
  nv?: [string, string][];
  pn?: [string, string][];
  attrs?: DemAttrSpec[];
  facets?: Record<string, string>;
  /** Custom element (not in the national XSD) — exported via dCustomResults. */
  custom?: boolean;
}

export interface DemGroupSpec {
  kind: "group";
  tag: string;
  label: string;
  repeat: boolean;
  min: number;
  /** Group attributes, e.g. UUID, CorrelationID. */
  attrs: string[];
  children: (DemFieldSpec | DemGroupSpec)[];
}

export type DemSpec = DemFieldSpec | DemGroupSpec;

/** One leaf occurrence: a value, or a Not Value (nv), optionally with PN / attributes. */
export interface DemFieldValue {
  v?: string;
  nv?: string;
  pn?: string;
  attrs?: Record<string, string>;
}

export interface DemNode {
  id: string;
  section: string;
  parent_id: string | null;
  tag: string;
  position: number;
  uuid: string | null;
  correlation_id: string | null;
  values: Record<string, DemFieldValue[]>;
}

export const DEM_SECTIONS = DEM_SECTION_SPECS;
export const DEM_LISTS = DEM_DEFINED_LISTS;

export const DEM_SECTION_LABELS: Record<string, string> = {
  dAgency: "Agency",
  dContact: "Contacts",
  dConfiguration: "Configuration",
  dLocation: "Locations",
  dVehicle: "Vehicles",
  dPersonnel: "Personnel",
  dDevice: "Devices",
  dFacility: "Facilities",
};

/** The custom Crew Member National EMS ID element on each personnel record. */
export const NATIONAL_EMS_ID = "dPersonnel.901";

export function findSpec(tag: string, specs: DemSpec[] = DEM_SECTIONS): DemSpec | undefined {
  for (const s of specs) {
    if (s.tag === tag) return s;
    if (s.kind === "group") {
      const r = findSpec(tag, s.children);
      if (r) return r;
    }
  }
  return undefined;
}

export function listOptions(key: string | null | undefined): [string, string][] {
  return key ? DEM_LISTS[key] ?? [] : [];
}

export function listLabel(key: string | null | undefined, code: string | undefined): string | undefined {
  if (!key || !code) return undefined;
  return DEM_LISTS[key]?.find(([c]) => c === code)?.[1];
}
